<?php require_once __DIR__.'/../config/config.php'; $oid=(int)($_GET['order']??0); ?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="../assets/css/style.css"><title>Order Tracking</title></head><body>
<div style="max-width:600px;margin:auto;padding:20px"><div class="card" style="text-align:center"><img src="<?=e(logo_url())?>" alt="<?=e(restaurant_name())?>" style="max-width:220px;max-height:130px;object-fit:contain;margin-bottom:8px"><div style="font-size:21px;font-weight:900;color:#c79a3a"><?=e(restaurant_name())?></div><h1>Order #<?=$oid?></h1><p id="status" class="pill">Checking…</p><div style="margin:30px 0;display:grid;grid-template-columns:repeat(4,1fr);gap:5px"><div id="s1">🛒<br>Placed</div><div id="s2">👨‍🍳<br>Preparing</div><div id="s3">🍽️<br>Ready</div><div id="s4">✓<br>Completed</div></div><p id="payment" class="muted"></p><button class="btn light" onclick="location.href='javascript:history.back()'">Back to Menu</button></div></div>
<script>const id=<?=$oid?>;async function poll(){const r=await fetch('../api/customer.php?action=status&order='+id);const j=await r.json();if(!j.ok)return;const o=j.order;document.getElementById('status').textContent=o.status.toUpperCase();document.getElementById('payment').textContent=o.payment_status==='paid'?'Payment received':'Payment: Pay at table / counter';const map={new:1,accepted:1,preparing:2,ready:3,served:3,completed:4,cancelled:0};let n=map[o.status]||1;for(let i=1;i<=4;i++)document.getElementById('s'+i).style.fontWeight=i<=n?'900':'400';}poll();setInterval(poll,5000);</script></body></html>